        }
    }
    console.log('═══════════════════════════════════════════');

    return {
        success: _results_.failed === 0,
        passed: _results_.passed,
        failed: _results_.failed
    };
}

if (typeof module !== 'undefined') {
    module.exports = { action: action };
}

