        var m = loadPure();
        assert.equal(m.buildAppendValue('Existing', 'Fresh'), 'Existing\n\n----\n\nFresh', 'separator between old and new');
        assert.equal(m.buildAppendValue('', 'Fresh'), 'Fresh', 'no separator without existing content');
    });

